-- deploy_all.sql : GENERATED by Infra/Sql/run-local.ps1 -BuildDeployAll from the numbered scripts. Do not edit by hand.
-- Production : connect to the application database, set @Target below to its name, run the whole file.
-- Re-runnable : each script is skipped when already logged in dbo.SchemaScriptLog.
-- Every script aborts (SET NOEXEC ON) when the connected database is not @Target / LeozApp / LeozApp_Test,
-- and a script whose predecessor failed refuses to run.

DECLARE @Target SYSNAME = N'<PRODUCTION_DATABASE_NAME>';
IF @Target = N'<PRODUCTION_DATABASE_NAME>' OR @Target <> DB_NAME()
BEGIN
	RAISERROR(N'deploy_all.sql : set @Target to the name of the database you are connected to. Aborted.', 16, 1);
	SET NOEXEC ON;
END
ELSE
	EXEC sys.sp_set_session_context @key = N'Leoz.TargetDb', @value = @Target;
GO

