DECLARE @Db SYSNAME = DB_NAME(), @Script NVARCHAR(128) = N'000_SchemaScriptLog';
IF @Db NOT IN (N'LeozApp', N'LeozApp_Test') AND @Db <> ISNULL(CAST(SESSION_CONTEXT(N'Leoz.TargetDb') AS SYSNAME), N'')
