		CONSTRAINT [PK_SchemaScriptLog] PRIMARY KEY ([ScriptName])
	);
END
GO

IF NOT EXISTS (SELECT 1 FROM [dbo].[SchemaScriptLog] WHERE [ScriptName] = N'000_SchemaScriptLog')
