-- =====================================================================================
-- 002_ProjectPermissions_Seed.sql
-- =====================================================================================
-- 002 : Project Detail module permissions - reference data + system-default rights (VendorId NULL) reproducing
--       the legacy rules of Infra/ProjectAccess.cs and ProjectController (see docs/permissions.md).
-- Re-runnable : skipped when already logged in SchemaScriptLog; inserts are NOT EXISTS guarded and never overwrite
-- existing rows (admin changes are kept). Only ALLOWED rows are seeded; anything not listed is denied.
-- Employee VIEW rows come from LOV.ProjectDetailTypeAccess (003_LOV_DesignationCode_Backfill.sql).
-- No DELETE / DELETE_FILE action : delete endpoints keep their legacy checks.

SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET ANSI_PADDING ON;
SET ANSI_WARNINGS ON;
SET ARITHABORT ON;
SET CONCAT_NULL_YIELDS_NULL ON;
SET NUMERIC_ROUNDABORT OFF;
SET XACT_ABORT ON;
SET NOCOUNT ON;
GO

-- Safety : only LeozApp / LeozApp_Test (or the database named in deploy_all.sql through SESSION_CONTEXT 'Leoz.TargetDb')
DECLARE @Db SYSNAME = DB_NAME(), @Script NVARCHAR(128) = N'002_ProjectPermissions_Seed';
IF @Db NOT IN (N'LeozApp', N'LeozApp_Test') AND @Db <> ISNULL(CAST(SESSION_CONTEXT(N'Leoz.TargetDb') AS SYSNAME), N'')
BEGIN
	RAISERROR(N'%s : database "%s" is not LeozApp / LeozApp_Test. Aborted.', 16, 1, @Script, @Db);
	SET NOEXEC ON;
END
ELSE IF OBJECT_ID(N'[dbo].[SchemaScriptLog]', N'U') IS NULL OR OBJECT_ID(N'[dbo].[ProjectModulePermission]', N'U') IS NULL
BEGIN
	RAISERROR(N'%s : run 000_SchemaScriptLog.sql and 001_ProjectPermissions_Schema.sql first. Aborted.', 16, 1, @Script);
	SET NOEXEC ON;
END
GO

IF EXISTS (SELECT 1 FROM [dbo].[SchemaScriptLog] WHERE [ScriptName] = N'002_ProjectPermissions_Seed')
BEGIN
	PRINT '002_ProjectPermissions_Seed : already applied, skipped.';
	SET NOEXEC ON;
END
GO

BEGIN TRANSACTION;

-- -------------------------------------------------------------------------------------
-- Reference data
-- -------------------------------------------------------------------------------------
INSERT INTO [dbo].[ProjectModule] ([Code], [Name], [DisplayOrder], [IsActive])
SELECT s.[Code], s.[Name], s.[DisplayOrder], 1
FROM (VALUES
	('EPM',    N'Estimate & Payment Terms', 1),
	('F3D',    N'Final 3D', 2),
	('DRW',    N'Drawings', 3),
	('WCLTSC', N'Client Scope of Work & Material Specifications', 4),
	('MB',     N'Mood Board', 5),
	('SITE',   N'Site Updates', 6),
	('WPEND',  N'Pending Selection & Work', 7),
	('MPRO',   N'Material Procurement', 8),
	('WCOMP',  N'Work Completion Report', 9)
) s ([Code], [Name], [DisplayOrder])
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[ProjectModule] m WHERE m.[Code] = s.[Code]);

INSERT INTO [dbo].[PermissionAction] ([Code], [Name])
SELECT s.[Code], s.[Name]
FROM (VALUES
	('VIEW',     N'View'),
	('ADD',      N'Add'),
	('EDIT',     N'Edit'),
	('APPROVE',  N'Approve'),
	('REJECT',   N'Reject'),
	('COMPLETE', N'Complete'),
	('ORDER',    N'Order'),
	('RECEIVE',  N'Receive')
) s ([Code], [Name])
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[PermissionAction] a WHERE a.[Code] = s.[Code]);

INSERT INTO [dbo].[ProjectModuleAction] ([ModuleCode], [ActionCode])
SELECT DISTINCT TRIM(m.[value]), TRIM(a.[value])
FROM (VALUES
	('EPM,F3D,DRW,WCLTSC,MB', 'VIEW,ADD,EDIT,APPROVE,REJECT'),
	('SITE',                  'VIEW,ADD,EDIT'),
	('WPEND',                 'VIEW,ADD,EDIT,COMPLETE,REJECT'),
	('MPRO',                  'VIEW,ADD,EDIT,ORDER,REJECT,RECEIVE'),
	('WCOMP',                 'VIEW,ADD,EDIT,APPROVE,REJECT')
) s ([Modules], [Actions])
CROSS APPLY STRING_SPLIT(s.[Modules], ',') m
CROSS APPLY STRING_SPLIT(s.[Actions], ',') a
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[ProjectModuleAction] x WHERE x.[ModuleCode] = TRIM(m.[value]) AND x.[ActionCode] = TRIM(a.[value]));

-- -------------------------------------------------------------------------------------
-- System-default rights
-- -------------------------------------------------------------------------------------
DECLARE @Subject TABLE ([SubjectCode] VARCHAR(30) PRIMARY KEY, [SubjectType] VARCHAR(12) NOT NULL);

INSERT INTO @Subject ([SubjectCode], [SubjectType]) VALUES
	('VENDOR', 'ACTOR'), ('CUSTOMER', 'ACTOR'),
	('MANAGER', 'DESIGNATION'), ('COORDINATOR', 'DESIGNATION'), ('SITE_SUPERVISOR', 'DESIGNATION'), ('SITE_ENGINEER', 'DESIGNATION'),
	('PURCHASER', 'DESIGNATION'), ('ARCHITECT', 'DESIGNATION'), ('SITE_VENDOR', 'DESIGNATION'), ('OTHER', 'DESIGNATION');

DECLARE @Rule TABLE ([Modules] VARCHAR(200), [Actions] VARCHAR(200), [Subjects] VARCHAR(300));

INSERT INTO @Rule ([Modules], [Actions], [Subjects]) VALUES
	-- Visibility : Vendor / Customer see all modules (employees : 003)
	('EPM,F3D,DRW,WCLTSC,MB,SITE,WPEND,MPRO,WCOMP', 'VIEW', 'VENDOR,CUSTOMER'),

	-- Document modules (legacy CanUpload / CanModify / CanApproveDoc / CanAddClientScope in Save_Doc, Save_Doc_Status "DOC")
	('EPM,F3D,DRW,MB',        'ADD',            'VENDOR,CUSTOMER,MANAGER,COORDINATOR,SITE_ENGINEER,ARCHITECT'),
	('WCLTSC',                'ADD',            'VENDOR'),
	('EPM,WCLTSC',            'EDIT',           'VENDOR,CUSTOMER,MANAGER'),
	('F3D,DRW,MB',            'EDIT',           'VENDOR,CUSTOMER,MANAGER,COORDINATOR,SITE_ENGINEER,ARCHITECT'),
	('EPM,F3D,DRW,WCLTSC,MB', 'APPROVE,REJECT', 'VENDOR,CUSTOMER,MANAGER,COORDINATOR'),

	-- Site Updates (Save_DailyUpdate : Employee.UserType = "COORD")
	('SITE', 'ADD,EDIT', 'COORDINATOR'),

	-- Pending Selection & Work (Save_WP : never Customer; Save_Doc_Status "WP" : CanModify)
	('WPEND', 'ADD',             'VENDOR,MANAGER,COORDINATOR,SITE_ENGINEER,ARCHITECT'),
	('WPEND', 'EDIT',            'VENDOR,MANAGER'),
	('WPEND', 'COMPLETE,REJECT', 'VENDOR,CUSTOMER,MANAGER'),

	-- Material Procurement (CanAddMaterial / CanUpdateMaterial / CanReceiveMaterial)
	('MPRO', 'ADD',               'VENDOR,CUSTOMER,MANAGER,COORDINATOR,SITE_SUPERVISOR,SITE_ENGINEER,SITE_VENDOR,OTHER'),
	('MPRO', 'EDIT,ORDER,REJECT', 'MANAGER'),
	('MPRO', 'RECEIVE',           'COORDINATOR'),

	-- Work Completion Report (APPROVE / REJECT : Customer only, intentional tightening of Save_Doc_Status "WC")
	('WCOMP', 'ADD,EDIT',       'MANAGER'),
	('WCOMP', 'APPROVE,REJECT', 'CUSTOMER');

DECLARE @Seed TABLE ([SubjectType] VARCHAR(12), [SubjectCode] VARCHAR(30), [ModuleCode] VARCHAR(10), [ActionCode] VARCHAR(20));

INSERT INTO @Seed ([SubjectType], [SubjectCode], [ModuleCode], [ActionCode])
SELECT sub.[SubjectType], sub.[SubjectCode], TRIM(m.[value]), TRIM(a.[value])
FROM @Rule r
CROSS APPLY STRING_SPLIT(r.[Modules], ',') m
CROSS APPLY STRING_SPLIT(r.[Actions], ',') a
CROSS APPLY STRING_SPLIT(r.[Subjects], ',') s
JOIN @Subject sub ON sub.[SubjectCode] = TRIM(s.[value]);

-- Guards : every subject token known, every (module, action) defined, no duplicates
IF (SELECT COUNT(*) FROM @Rule r CROSS APPLY STRING_SPLIT(r.[Modules], ',') m CROSS APPLY STRING_SPLIT(r.[Actions], ',') a CROSS APPLY STRING_SPLIT(r.[Subjects], ',') s)
	<> (SELECT COUNT(*) FROM @Seed)
	THROW 50001, 'Seed contains an unknown subject code.', 1;

IF EXISTS (SELECT 1 FROM @Seed s WHERE NOT EXISTS (SELECT 1 FROM [dbo].[ProjectModuleAction] x WHERE x.[ModuleCode] = s.[ModuleCode] AND x.[ActionCode] = s.[ActionCode]))
	THROW 50002, 'Seed contains a module/action that is not defined in ProjectModuleAction.', 1;

IF EXISTS (SELECT 1 FROM @Seed GROUP BY [SubjectType], [SubjectCode], [ModuleCode], [ActionCode] HAVING COUNT(*) > 1)
	THROW 50003, 'Seed contains duplicate subject/module/action rows.', 1;

INSERT INTO [dbo].[ProjectModulePermission] ([VendorId], [SubjectType], [SubjectCode], [ModuleCode], [ActionCode], [IsAllowed], [Scope], [IsActive], [IsDeleted], [CreatedBy], [CreatedDate], [LastModifiedBy], [LastModifiedDate])
SELECT NULL, s.[SubjectType], s.[SubjectCode], s.[ModuleCode], s.[ActionCode], 1, 'ALL', 1, 0, 1, GETDATE(), 1, GETDATE()
FROM @Seed s
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[ProjectModulePermission] p
				  WHERE p.[VendorId] IS NULL AND p.[SubjectType] = s.[SubjectType] AND p.[SubjectCode] = s.[SubjectCode]
				  AND p.[ModuleCode] = s.[ModuleCode] AND p.[ActionCode] = s.[ActionCode]);

DECLARE @Inserted INT = @@ROWCOUNT, @SeedCount INT = (SELECT COUNT(*) FROM @Seed);
PRINT CONCAT('ProjectModulePermission : ', @Inserted, ' system-default row(s) inserted (', @SeedCount, ' in seed).');

UPDATE [dbo].[PermissionVersion] SET [Version] = [Version] + 1 WHERE [Id] = 1;

INSERT INTO [dbo].[SchemaScriptLog] ([ScriptName], [AppliedOn]) VALUES (N'002_ProjectPermissions_Seed', SYSDATETIME());

COMMIT TRANSACTION;
PRINT '002_ProjectPermissions_Seed : applied.';
GO

SET NOEXEC OFF;
GO

-- =====================================================================================
-- 003_LOV_DesignationCode_Backfill.sql
-- =====================================================================================
-- 003 : one-time migration of LOV USER_TYPE rows to Project Detail permissions (see docs/permissions.md).
--   1. Backfill LOV.DesignationCode with the rules of the legacy ProjectAccess.ResolveDesignation (only where NULL).
--   2. Employee VIEW rights : LOV.ProjectDetailTypeAccess ("ALL" or CSV of module codes) -> ProjectModulePermission
--      (VendorId NULL, DESIGNATION / DesignationCode, VIEW). LOV rows mapping to the same designation are UNIONed.
--   3. Report (result sets R1..R7), including the COORD / COORDINATOR mismatch list (R7).
-- Re-runnable : skipped when already logged in SchemaScriptLog; existing DesignationCode values and permission rows are never overwritten.

SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET ANSI_PADDING ON;
SET ANSI_WARNINGS ON;
SET ARITHABORT ON;
SET CONCAT_NULL_YIELDS_NULL ON;
SET NUMERIC_ROUNDABORT OFF;
SET XACT_ABORT ON;
SET NOCOUNT ON;
GO

-- Safety : only LeozApp / LeozApp_Test (or the database named in deploy_all.sql through SESSION_CONTEXT 'Leoz.TargetDb')
DECLARE @Db SYSNAME = DB_NAME(), @Script NVARCHAR(128) = N'003_LOV_DesignationCode_Backfill';
IF @Db NOT IN (N'LeozApp', N'LeozApp_Test') AND @Db <> ISNULL(CAST(SESSION_CONTEXT(N'Leoz.TargetDb') AS SYSNAME), N'')
BEGIN
	RAISERROR(N'%s : database "%s" is not LeozApp / LeozApp_Test. Aborted.', 16, 1, @Script, @Db);
	SET NOEXEC ON;
END
ELSE IF OBJECT_ID(N'[dbo].[SchemaScriptLog]', N'U') IS NULL
	OR NOT EXISTS (SELECT 1 FROM [dbo].[SchemaScriptLog] WHERE [ScriptName] = N'002_ProjectPermissions_Seed')
BEGIN
	RAISERROR(N'%s : run 000, 001 and 002 first. Aborted.', 16, 1, @Script);
	SET NOEXEC ON;
END
GO

IF EXISTS (SELECT 1 FROM [dbo].[SchemaScriptLog] WHERE [ScriptName] = N'003_LOV_DesignationCode_Backfill')
BEGIN
	PRINT '003_LOV_DesignationCode_Backfill : already applied, skipped.';
	SET NOEXEC ON;
END
GO

BEGIN TRANSACTION;

-- Whitespace trimmed by C# string.Trim() for these values
DECLARE @ws NVARCHAR(10) = CONCAT(N' ', NCHAR(9), NCHAR(10), NCHAR(13));

-- -------------------------------------------------------------------------------------
-- 1. Backfill DesignationCode (mirror of ProjectAccess.ResolveDesignation, same order of checks :
--    code upper-cased; description lower-cased without "-" and " ")
-- -------------------------------------------------------------------------------------
UPDATE l
SET l.[DesignationCode] =
	CASE
		WHEN c.[Code] = N'MNGR'  OR c.[Descr] LIKE N'%manager%'     THEN 'MANAGER'
		WHEN c.[Code] = N'COORD' OR c.[Descr] LIKE N'%coordinator%' THEN 'COORDINATOR'
		WHEN c.[Code] = N'PUR'   OR c.[Descr] LIKE N'%purchase%'    THEN 'PURCHASER'
		WHEN c.[Descr] LIKE N'%supervisor%'                         THEN 'SITE_SUPERVISOR'
		WHEN c.[Descr] LIKE N'%engineer%'                           THEN 'SITE_ENGINEER'
		WHEN c.[Descr] LIKE N'%architect%'                          THEN 'ARCHITECT'
		WHEN c.[Descr] LIKE N'%vendor%'                             THEN 'SITE_VENDOR'
		ELSE 'OTHER'
	END
FROM [dbo].[LOV] l
CROSS APPLY (SELECT UPPER(TRIM(@ws FROM ISNULL(l.[LOV_Code], N''))) AS [Code],
					REPLACE(REPLACE(LOWER(TRIM(@ws FROM ISNULL(l.[LOV_Desc], N''))), N'-', N''), N' ', N'') AS [Descr]) c
WHERE l.[LOV_Column] = N'USER_TYPE' AND l.[DesignationCode] IS NULL;

PRINT CONCAT('LOV.DesignationCode backfilled : ', @@ROWCOUNT, ' row(s).');

-- -------------------------------------------------------------------------------------
-- 2. Employee VIEW rows (legacy HasModule : CSV split on ",", trimmed, case-sensitive match on module code or "ALL")
-- -------------------------------------------------------------------------------------
DECLARE @View TABLE ([DesignationCode] VARCHAR(30), [ModuleCode] VARCHAR(10), PRIMARY KEY ([DesignationCode], [ModuleCode]));

INSERT INTO @View ([DesignationCode], [ModuleCode])
SELECT DISTINCT l.[DesignationCode], m.[Code]
FROM [dbo].[LOV] l
CROSS APPLY STRING_SPLIT(ISNULL(l.[ProjectDetailTypeAccess], N''), N',') t
JOIN [dbo].[ProjectModule] m
	ON TRIM(@ws FROM t.[value]) COLLATE Latin1_General_CS_AS = N'ALL'
	OR TRIM(@ws FROM t.[value]) COLLATE Latin1_General_CS_AS = CAST(m.[Code] AS NVARCHAR(10)) COLLATE Latin1_General_CS_AS
WHERE l.[LOV_Column] = N'USER_TYPE' AND l.[DesignationCode] IS NOT NULL;

INSERT INTO [dbo].[ProjectModulePermission] ([VendorId], [SubjectType], [SubjectCode], [ModuleCode], [ActionCode], [IsAllowed], [Scope], [IsActive], [IsDeleted], [CreatedBy], [CreatedDate], [LastModifiedBy], [LastModifiedDate])
SELECT NULL, 'DESIGNATION', v.[DesignationCode], v.[ModuleCode], 'VIEW', 1, 'ALL', 1, 0, 1, GETDATE(), 1, GETDATE()
FROM @View v
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[ProjectModulePermission] p
				  WHERE p.[VendorId] IS NULL AND p.[SubjectType] = 'DESIGNATION' AND p.[SubjectCode] = v.[DesignationCode]
				  AND p.[ModuleCode] = v.[ModuleCode] AND p.[ActionCode] = 'VIEW');

PRINT CONCAT('ProjectModulePermission : ', @@ROWCOUNT, ' employee VIEW row(s) inserted.');

UPDATE [dbo].[PermissionVersion] SET [Version] = [Version] + 1 WHERE [Id] = 1;

INSERT INTO [dbo].[SchemaScriptLog] ([ScriptName], [AppliedOn]) VALUES (N'003_LOV_DesignationCode_Backfill', SYSDATETIME());

COMMIT TRANSACTION;
PRINT '003_LOV_DesignationCode_Backfill : applied.';
GO

-- =====================================================================================
-- Report (read-only)
-- =====================================================================================

-- R1. LOV USER_TYPE -> designation, old CSV
SELECT 'R1_LOV_DESIGNATION' AS [Report], l.[LOV_Code], l.[LOV_Desc], l.[DesignationCode], ISNULL(l.[ProjectDetailTypeAccess], N'') AS [Old_ProjectDetailTypeAccess]
FROM [dbo].[LOV] l
WHERE l.[LOV_Column] = N'USER_TYPE'
ORDER BY l.[DisplayOrder], l.[LOV_Code];

-- R2. Designations fed by more than one LOV row (their module lists were UNIONed - review)
SELECT 'R2_MERGED_DESIGNATIONS' AS [Report], l.[DesignationCode],
	STRING_AGG(CONCAT(l.[LOV_Code], N' [', ISNULL(l.[ProjectDetailTypeAccess], N''), N']'), N' | ') AS [Merged_LOV_Rows]
FROM [dbo].[LOV] l
WHERE l.[LOV_Column] = N'USER_TYPE'
GROUP BY l.[DesignationCode]
HAVING COUNT(*) > 1;

-- R3. Designation : old CSV(s) vs new VIEW rows (system default)
SELECT 'R3_VIEW_ROWS' AS [Report], d.[DesignationCode],
	(SELECT STRING_AGG(CONCAT(l.[LOV_Code], N'=', ISNULL(NULLIF(l.[ProjectDetailTypeAccess], N''), N'(empty)')), N' | ') FROM [dbo].[LOV] l WHERE l.[LOV_Column] = N'USER_TYPE' AND l.[DesignationCode] = d.[DesignationCode]) AS [Old_CSV],
	(SELECT STRING_AGG(p.[ModuleCode], ',') WITHIN GROUP (ORDER BY m.[DisplayOrder])
	 FROM [dbo].[ProjectModulePermission] p JOIN [dbo].[ProjectModule] m ON m.[Code] = p.[ModuleCode]
	 WHERE p.[VendorId] IS NULL AND p.[SubjectType] = 'DESIGNATION' AND p.[SubjectCode] = d.[DesignationCode]
	 AND p.[ActionCode] = 'VIEW' AND p.[IsAllowed] = 1 AND p.[IsActive] = 1 AND p.[IsDeleted] = 0) AS [New_VIEW_Modules]
FROM (VALUES ('MANAGER', 1), ('COORDINATOR', 2), ('SITE_SUPERVISOR', 3), ('SITE_ENGINEER', 4), ('PURCHASER', 5), ('ARCHITECT', 6), ('SITE_VENDOR', 7), ('OTHER', 8)) d ([DesignationCode], [Ord])
ORDER BY d.[Ord];

-- R4. CSV tokens that match no module (ignored by legacy HasModule too, e.g. wrong case / typo)
SELECT 'R4_IGNORED_TOKENS' AS [Report], l.[LOV_Code], x.[Token]
FROM [dbo].[LOV] l
CROSS APPLY STRING_SPLIT(ISNULL(l.[ProjectDetailTypeAccess], N''), N',') t
CROSS APPLY (SELECT TRIM(CONCAT(N' ', NCHAR(9), NCHAR(10), NCHAR(13)) FROM t.[value]) AS [Token]) x
WHERE l.[LOV_Column] = N'USER_TYPE'
AND x.[Token] <> N''
AND x.[Token] COLLATE Latin1_General_CS_AS <> N'ALL'
AND NOT EXISTS (SELECT 1 FROM [dbo].[ProjectModule] m WHERE CAST(m.[Code] AS NVARCHAR(10)) COLLATE Latin1_General_CS_AS = x.[Token] COLLATE Latin1_General_CS_AS);

-- R5. Duplicate USER_TYPE codes (login uses the first row found)
SELECT 'R5_DUPLICATE_CODES' AS [Report], l.[LOV_Code], COUNT(*) AS [Rows]
FROM [dbo].[LOV] l
WHERE l.[LOV_Column] = N'USER_TYPE'
GROUP BY l.[LOV_Code]
HAVING COUNT(*) > 1;

-- R6. Employees whose UserType has no LOV USER_TYPE row (no modules today, none after migration)
SELECT 'R6_EMPLOYEES_WITHOUT_LOV' AS [Report], e.[UserType], COUNT(*) AS [Employees]
FROM [dbo].[Employee] e
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[LOV] l WHERE l.[LOV_Column] = N'USER_TYPE' AND l.[LOV_Code] = e.[UserType])
GROUP BY e.[UserType];

-- R7. COORD / COORDINATOR mismatches : today Save_DailyUpdate checks Employee.UserType = 'COORD',
--     Can("SITE", ADD/EDIT) checks designation COORDINATOR. Any row here changes who may save daily updates.
SELECT 'R7_COORD_MISMATCH' AS [Report], l.[LOV_Code], l.[LOV_Desc], l.[DesignationCode],
	CASE WHEN l.[LOV_Code] = N'COORD' THEN 'yes' ELSE 'no' END AS [Today_Can_Save_DailyUpdate],
	CASE WHEN l.[DesignationCode] = 'COORDINATOR' THEN 'yes' ELSE 'no' END AS [New_Can_Save_DailyUpdate],
	(SELECT COUNT(*) FROM [dbo].[Employee] e WHERE e.[UserType] = l.[LOV_Code]) AS [Employees],
	(SELECT COUNT(*) FROM [dbo].[Employee] e WHERE e.[UserType] = l.[LOV_Code] AND e.[IsActive] = 1) AS [Active_Employees]
FROM [dbo].[LOV] l
WHERE l.[LOV_Column] = N'USER_TYPE'
AND ((l.[DesignationCode] = 'COORDINATOR' AND l.[LOV_Code] <> N'COORD')
	OR (l.[LOV_Code] = N'COORD' AND ISNULL(l.[DesignationCode], '') <> 'COORDINATOR'));

IF @@ROWCOUNT = 0 PRINT 'R7_COORD_MISMATCH : none (every COORDINATOR row has code COORD and vice versa).';
GO

SET NOEXEC OFF;
GO

-- =====================================================================================
-- 004_ModuleAccess_Menu.sql
-- =====================================================================================
-- 004 : "Module Access" menu (Areas/Admin/Controllers/ModuleAccessController) under Configuration,
--       readable by Admin (role 2) and Vendor (role 3). Super Admin (role 1) sees every menu.
--       Existing Admin / Vendor users get the menu in UserMenuAccess (new users copy RoleMenuAccess).
-- Re-runnable : skipped when already logged in SchemaScriptLog; inserts are NOT EXISTS guarded.

SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET XACT_ABORT ON;
SET NOCOUNT ON;
GO

-- Safety : only LeozApp / LeozApp_Test (or the database named in deploy_all.sql through SESSION_CONTEXT 'Leoz.TargetDb')
DECLARE @Db SYSNAME = DB_NAME(), @Script NVARCHAR(128) = N'004_ModuleAccess_Menu';
IF @Db NOT IN (N'LeozApp', N'LeozApp_Test') AND @Db <> ISNULL(CAST(SESSION_CONTEXT(N'Leoz.TargetDb') AS SYSNAME), N'')
BEGIN
	RAISERROR(N'%s : database "%s" is not LeozApp / LeozApp_Test. Aborted.', 16, 1, @Script, @Db);
	SET NOEXEC ON;
END
ELSE IF OBJECT_ID(N'[dbo].[SchemaScriptLog]', N'U') IS NULL
	OR NOT EXISTS (SELECT 1 FROM [dbo].[SchemaScriptLog] WHERE [ScriptName] = N'003_LOV_DesignationCode_Backfill')
BEGIN
	RAISERROR(N'%s : run 000 to 003 first. Aborted.', 16, 1, @Script);
	SET NOEXEC ON;
END
GO

IF EXISTS (SELECT 1 FROM [dbo].[SchemaScriptLog] WHERE [ScriptName] = N'004_ModuleAccess_Menu')
BEGIN
	PRINT '004_ModuleAccess_Menu : already applied, skipped.';
	SET NOEXEC ON;
END
GO

BEGIN TRANSACTION;

DECLARE @ParentId BIGINT = (SELECT TOP 1 [Id] FROM [dbo].[Menu] WHERE [ParentId] = 0 AND [Name] = N'Configuration' AND [IsDeleted] = 0 ORDER BY [Id]);

IF @ParentId IS NULL
	THROW 50040, '004_ModuleAccess_Menu : parent menu "Configuration" not found.', 1;

IF NOT EXISTS (SELECT 1 FROM [dbo].[Menu] WHERE [Area] = N'Admin' AND [Controller] = N'ModuleAccess' AND [IsDeleted] = 0)
	INSERT INTO [dbo].[Menu] ([ParentId], [Area], [Controller], [Url], [Name], [Icon], [DisplayOrder], [CreatedBy], [CreatedDate], [LastModifiedBy], [LastModifiedDate], [IsSuperAdmin], [IsAdmin], [IsActive], [IsDeleted])
	VALUES (@ParentId, N'Admin', N'ModuleAccess', NULL, N'Module Access', N'bi bi-ui-checks-grid', 6, 1, GETDATE(), 1, GETDATE(), 0, 0, 1, 0);

DECLARE @MenuId BIGINT = (SELECT TOP 1 [Id] FROM [dbo].[Menu] WHERE [Area] = N'Admin' AND [Controller] = N'ModuleAccess' AND [IsDeleted] = 0 ORDER BY [Id]);

-- Role access : Admin (2), Vendor (3). Delete flag is not used by this screen.
INSERT INTO [dbo].[RoleMenuAccess] ([RoleId], [MenuId], [IsRead], [IsCreate], [IsUpdate], [IsDelete], [CreatedBy], [CreatedDate], [LastModifiedBy], [LastModifiedDate], [IsActive], [IsDeleted])
SELECT r.[Id], @MenuId, 1, 1, 1, 0, 1, GETDATE(), 1, GETDATE(), 1, 0
FROM [dbo].[Roles] r
WHERE r.[Id] IN (2, 3)
AND NOT EXISTS (SELECT 1 FROM [dbo].[RoleMenuAccess] x WHERE x.[RoleId] = r.[Id] AND x.[MenuId] = @MenuId);

PRINT CONCAT('RoleMenuAccess : ', @@ROWCOUNT, ' row(s) inserted.');

-- Existing Admin / Vendor users (menus are loaded from UserMenuAccess at login)
INSERT INTO [dbo].[UserMenuAccess] ([UserId], [RoleId], [MenuId], [IsRead], [IsCreate], [IsUpdate], [IsDelete], [CreatedBy], [CreatedDate], [LastModifiedBy], [LastModifiedDate], [IsActive], [IsDeleted])
SELECT DISTINCT m.[UserId], m.[RoleId], @MenuId, 1, 1, 1, 0, 1, GETDATE(), 1, GETDATE(), 1, 0
FROM [dbo].[UserRoleMapping] m
WHERE m.[RoleId] IN (2, 3) AND m.[IsActive] = 1 AND m.[IsDeleted] = 0
AND NOT EXISTS (SELECT 1 FROM [dbo].[UserMenuAccess] x WHERE x.[UserId] = m.[UserId] AND x.[RoleId] = m.[RoleId] AND x.[MenuId] = @MenuId);

PRINT CONCAT('UserMenuAccess : ', @@ROWCOUNT, ' row(s) inserted.');

INSERT INTO [dbo].[SchemaScriptLog] ([ScriptName], [AppliedOn]) VALUES (N'004_ModuleAccess_Menu', SYSDATETIME());

COMMIT TRANSACTION;
PRINT '004_ModuleAccess_Menu : applied.';
GO

SET NOEXEC OFF;
GO

